use std::fmt::Display;

fn longest_with_an_announcement<'a, T>(x: &'a str, y: &'a str, ann: T) -> &'a str
where
    T: Display,
{
    println!("Announcement! {ann}");
    if x.len() > y.len() { x } else { y }
}

fn main() {
    let s: &'static str = "I have a static lifetime.";
    println!("{}", longest_with_an_announcement(s, "short", 42));
}

fn pick_first(a: &str, b: &str) -> &str {
    println!("ignoring {}", b.len());
    a
}

fn longer(a: &str, b: &str) -> &str {
    if b.len() > a.len() { b } else { a }
}

fn main() {
    let keep = String::from("apple");
    let chosen;
    {
        let temp = String::from("kiwi");
        chosen = pick_first(&keep, &temp);
    }
    println!("{chosen}");
    println!("{}", longer("pear", "banana"));
}
